SELECT id, session_id, duration_sec, CUME_DIST() OVER (PARTITION BY page, event_type ORDER BY duration_sec DESC) AS duration_sec_cume_dist, SUM(duration_sec) OVER (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec, NTILE(4) OVER (PARTITION BY event_type, session_id ORDER BY duration_sec DESC, id) AS duration_sec_bucket FROM web_events;
